pub const CONTENT_TYPE:&str="application/vnd.aurora.adaptive.posterior-integrity-card-1+json";
pub const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PanelObservation4{pub observation_id:String,pub capability_id:String,pub parent_id:String,pub outcome:String,pub effective_n_milli:u64,pub parent_fraction_milli:u32,pub evidence_digest:ContentHash,pub policy_epoch:u64,pub negative_result:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PosteriorIntegrityRequest4{pub request_id:String,pub purpose:String,pub observations:Vec<PanelObservation4>,pub required_observation_order:Vec<String>,pub required_capability_order:Vec<String>,pub minimum_effective_n_milli:u64,pub maximum_parent_fraction_milli:u32,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub action_budget:u32,pub action_count:u32,pub boundary:String}
