#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PosteriorIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub purpose:String,pub disposition:String,pub observation_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub capability_order:Vec<String>,pub parent_order:Vec<String>,pub effective_n_order:Vec<String>,pub cluster_penalty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub replay_identity:ContentHash,pub closure_digest:ContentHash,pub artifact:PosteriorIntegrityArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum PosteriorIntegrityError{#[error("invalid posterior-integrity request: {0}")]Invalid(String),#[error("posterior-integrity card failed validation: {0}")]Output(String)}
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn nonempty(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":"1.0.0","capability_id":id,"version":version,"owner_crate":"adaptive","consumers":["panel scheduler","evaluation engine","coverage gate","release auditor"],"behavior":format!("qualify clustered adaptive posterior at {scale} ({mode})"),"value":"prevents parent-cluster inflation and unknown outcomes from becoming false precision","input_schema":"PosteriorIntegrityRequest4@1","output_schema":"PosteriorIntegrityCard7@1","effects":["emit:posterior-card","retain:cluster-penalty","block:unsafe-evaluation"],"permissions":["read:local-panel"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
impl PosteriorIntegrityCard7{pub fn validate(&self)->Result<(),PosteriorIntegrityError>{if self.schema_version!="1.0.0"||!nonempty(&self.contract_version)||!nonempty(&self.feature_id)||!nonempty(&self.mode)||!nonempty(&self.scale)||!nonempty(&self.request_id)||!nonempty(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.observation_order.is_empty()||!ordered(&self.observation_order)||!ordered(&self.accepted_order)||!ordered(&self.rejected_order)||!ordered(&self.unknown_order)||!ordered(&self.omitted_order)||!ordered(&self.capability_order)||!ordered(&self.parent_order)||!ordered(&self.effective_n_order)||!ordered(&self.cluster_penalty_order)||!ordered(&self.negative_evidence_order)||!digest(&self.replay_identity)||!digest(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=BOUNDARY{return Err(PosteriorIntegrityError::Output("posterior identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.observation_order.iter().cloned());let states=self.accepted_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.observation_order.len()||states.len()!=ids.len()||BTreeSet::from_iter(states)!=ids{return Err(PosteriorIntegrityError::Output("observation states do not partition".into()))}Ok(())}}
pub fn qualify(request:&PosteriorIntegrityRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<PosteriorIntegrityCard7,PosteriorIntegrityError>{if !nonempty(&request.request_id)||!nonempty(&request.purpose)||request.observations.is_empty()||request.required_observation_order.is_empty()||request.required_capability_order.is_empty()||request.minimum_effective_n_milli==0||request.maximum_parent_fraction_milli>1000||!digest(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ordered(&request.required_observation_order)||!ordered(&request.required_capability_order)||!ordered(&request.adversarial_events){return Err(PosteriorIntegrityError::Invalid("posterior identity, requirements, thresholds, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.observations.clone();rows.sort_by(|a,b|a.observation_id.cmp(&b.observation_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut capabilities=BTreeSet::new();let mut parents=BTreeSet::new();let mut ns=BTreeSet::new();let mut penalties=BTreeSet::new();let mut negative=BTreeSet::new();let mut digests=BTreeSet::new();for o in &rows{if !seen.insert(o.observation_id.clone())||!nonempty(&o.observation_id)||!nonempty(&o.capability_id)||!nonempty(&o.parent_id)||!nonempty(&o.outcome)||!digest(&o.evidence_digest)||!o.local||!o.aggregate_only{return Err(PosteriorIntegrityError::Invalid("observation identity, outcome, evidence, or locality is invalid".into()))}order.push(o.observation_id.clone());capabilities.insert(o.capability_id.clone());parents.insert(o.parent_id.clone());ns.insert(format!("{}:{}",o.observation_id,o.effective_n_milli));penalties.insert(format!("{}:{}",o.observation_id,o.parent_fraction_milli));digests.insert(o.evidence_digest.clone());if o.negative_result{negative.insert(format!("{}:negative-result",o.observation_id));}if o.policy_epoch==0||o.outcome=="unknown"{unknown.insert(o.observation_id.clone());}else if o.effective_n_milli<request.minimum_effective_n_milli||o.parent_fraction_milli>request.maximum_parent_fraction_milli||o.outcome=="contradicted"{rejected.insert(o.observation_id.clone());}else if o.evidence_digest==request.replay_identity||!request.required_observation_order.contains(&o.observation_id){omitted.insert(o.observation_id.clone());}else{accepted.insert(o.observation_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let missing=!request.required_observation_order.iter().all(|o|seen.contains(o))||!request.required_capability_order.iter().all(|c|capabilities.contains(c));let disposition=if global{"blocked"}else if missing{"unknown"}else if !rejected.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"observation_order":order,"accepted_order":accepted.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"capability_order":capabilities.into_iter().collect::<Vec<_>>(),"parent_order":parents.into_iter().collect::<Vec<_>>(),"effective_n_order":ns.into_iter().collect::<Vec<_>>(),"cluster_penalty_order":penalties.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let hash=ContentHash::of_value(&payload).map_err(|e|PosteriorIntegrityError::Output(e.to_string()))?;payload["closure_digest"]=json!(hash);payload["artifact"]=json!({"artifact_id":format!("adaptive-posterior:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":hash,"semantic_loss":payload["omitted_order"],"evidence_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:posterior-card:{}",request.request_id)]}else{vec!["block:unsafe-evaluation".to_string()]});let out:PosteriorIntegrityCard7=serde_json::from_value(payload).map_err(|e|PosteriorIntegrityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
